def process_batch(order_list):
    total_revenue = 0.0
    failed_orders = []
    for item in order_list:
        try:
            total_revenue += item['amount'] * item['quantity']
        except (KeyError, TypeError):
            if isinstance(item, dict):
                failed_orders.append(item.get('id'))
            else:
                failed_orders.append(None)
    return (total_revenue, failed_orders)
